window.NEWS=[{"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=8d01244b-2d7b-4fbb-abd9-6ca7ad8a06de", "title": "客家幣2.0正式啟動 發放17萬份打造講客生活圈", "date": "2026-10-29", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "客家委員會與中央銀行及金融、電子支付機構代表28日上午於臺北西門紅樓舉辦客家幣2.0宣告記者會，由主任委員古秀妃共同揭開序幕。客家幣2.0將發放17萬份並擴大使用範圍至全臺，鼓勵民眾在日常消費中開口講客語，並攜手全臺合作店家打造講客生活圈。發放對象除通過客語認證者及獲表揚客語家庭外，增加修讀客語文課程及參與客家藝文競賽師生，預計自12月中旬起陸續發放。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=8d01244b-2d7b-4fbb-abd9-6ca7ad8a06de"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=e4a45992-b06d-403a-9182-a18ffc52bbe1", "title": "「2027桐花祭」即日起至115年11月30日受理申請", "date": "2026-10-28", "category": "政策與補助", "unit": "客家委員會全球資訊網", "summary": "客家委員會依《客家文藝復興補助作業要點》公告，補助直轄市及縣(市)政府於116年3月至5月在「樟之細路」或賞桐步道舉辦健行、文化與環境教育活動，提案期限即日起至115年11月30日截止，每縣（市）補助上限新臺幣90萬元。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=e4a45992-b06d-403a-9182-a18ffc52bbe1"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=9ab614b0-d27b-4fbf-81e7-b92e347bcfa3", "title": "2026客家影像展免費索票開跑 21部精采作品邀民眾走進光影世界", "date": "2026-10-28", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "客家委員會宣布2026客家影像展將於11月7日至8日在臺北光點華山電影館首展，之後於11月15日新竹市影像博物館、11月21日至22日高雄市電影館接續放映。展覽以「水」為主題，精選21部國內外作品，採免費索票方式入場，臺北場已於10月27日開放線上索票，新竹與高雄分別於11月2日、11月9日上午10時開放索票。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=9ab614b0-d27b-4fbf-81e7-b92e347bcfa3"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=760796a9-3b02-4edf-8ec8-82f6359c7b59", "title": "「客家幣 2.0」發放對象及領取方式", "date": "2026-10-28", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "客家委員會於10月28日公告客家幣2.0發放對象，包括115年度獲表揚客語家庭成員、通過客語能力認證者、18歲以下修讀本土語文課程的學生與教學人員、參加客語競賽的師生及行政作業人員，依資格發放1,000至5,000元不等。符合第(一)與第(二)項者免申辦，由本會主動發放；其餘對象須於11月30日前或3月1日至3月31日自行線上申請，並於12月中旬寄送QR Code，使用期限至次年10月31日。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=760796a9-3b02-4edf-8ec8-82f6359c7b59"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=6cd9865d-c606-4de5-80df-cc2e2df23668", "title": "灣區親子體驗客家艾草粄DIY 手作美食傳承客家文化", "date": "2026-10-28", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "北加州臺灣客家會於10月24日在金山灣區文教中心舉辦「客家艾草粄DIY」親子活動，超過60名家庭參與，透過傳統米食製作、客語教學與文化介紹，讓海外下一代體驗客家飲食與語言。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=6cd9865d-c606-4de5-80df-cc2e2df23668"}, {"id": "https://www.cna.com.tw/news/ahel/202610280314.aspx", "title": "客家幣2.0啟動 12月中旬起發17萬份全台可用", "date": "2026-10-28", "category": "客家文化", "unit": "中央社", "summary": "客家委員會（客委會）於10月28日宣布客家幣2.0啟動，12月中旬發放17萬份。發放對象包括115年客語認證者、獲表揚客語家庭、修讀客語課程師生（雙軌申領）及參與客家藝文競賽師生（免登記），分別給予1000、3000、5000或500元獎勵。客家幣可透過20家金融、電子支付機構領取，於全台逾650家講客店家消費使用，使用期間自12月15日至次年10月31日。", "sample": false, "url": "https://www.cna.com.tw/news/ahel/202610280314.aspx"}, {"id": "https://www.touwu.gov.tw/News_Content.aspx?n=3460&s=1007532", "title": "苗栗2026風箏文化暨客家美食節因受颱風影響延期至11月6日至8日在苗栗市河濱公園舉辦，歡迎大家前來欣賞精彩風箏表演、逛美食市集！", "date": "2026-10-27", "category": "產業與觀光", "unit": "頭屋鄉公所", "summary": "因颱風影響，苗栗2026風箏文化暨客家美食節延期至11月6日至8日，於苗栗市河濱公園舉行，歡迎民眾前往欣賞風箏表演並逛美食市集。", "sample": false, "url": "https://www.touwu.gov.tw/News_Content.aspx?n=3460&s=1007532", "topic": "產業報導"}, {"id": "https://ezgo.ardswc.gov.tw/zh-tw/event/5509/", "title": "從果香到米香，走進客庄的一天", "date": "2026-10-27", "category": "客庄新聞", "unit": "農業易遊網", "summary": "河背庒農園舉辦客庄食農體驗，一日行程包括09:30–11:30的酸檸茶體驗（680元）、11:30–13:00的客家割稻飯（200元）以及13:00–15:00的客家米食體驗（500元），每人總價1,380元，歡迎親友、社團或企業團體報名參加。", "sample": false, "url": "https://ezgo.ardswc.gov.tw/zh-tw/event/5509/"}, {"id": "https://www.mlcg.gov.tw/News_Content.aspx?n=2546&s=1007512", "title": "粄香傳客情・好禮展風華 2026貓裏客家粄食文化節結合115年苗栗市特色伴手禮頒獎", "date": "2026-10-26", "category": "客家文化", "unit": "苗栗市公所", "summary": "苗栗市公所在10月26日於貓裏喵親子公園舉辦「2026貓裏客家粄食文化節」，結合客家美食與「115年苗栗市特色伴手禮徵件活動」頒獎，吸引約3,000人參與。活動頒發總獎金新臺幣11萬元，獎項分食組與品組，並透過線上人氣票選選出貓裏人氣獎。", "sample": false, "url": "https://www.mlcg.gov.tw/News_Content.aspx?n=2546&s=1007512", "topic": "產業報導"}, {"id": "https://www.miaoli.gov.tw/general_affairs/News_Content.aspx?n=851&sms=9702&s=1007517", "title": "行政處-苗栗客家歌手演唱會巨蛋登場縣長鍾東錦獻唱「平板」山歌炒熱氣氛", "date": "2026-10-26", "category": "客家文化", "unit": "苗栗縣", "summary": "苗栗市公所主辦的「115年苗栗市客家歌手演唱會」於苗栗巨蛋體育館舉行，縣長鍾東錦應民眾要求獻唱傳統山歌「平板」，並呼籲年輕人多說客家話，強調文化傳承。", "sample": false, "url": "https://www.miaoli.gov.tw/general_affairs/News_Content.aspx?n=851&sms=9702&s=1007517"}, {"id": "https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=1007509", "title": "2026貓裏客家粄食文化節 民眾大啖客家美食逛客庄好物", "date": "2026-10-26", "category": "客庄新聞", "unit": "苗栗縣", "summary": "由苗栗市公所主辦的「2026貓裏客家粄食文化節」於26日上午在貓裏喵親子公園舉行，主題為「粄香傳客情・共創新食代」。苗栗縣副縣長邱俐俐、立法委員特助張鵬輝等人出席，推廣客家飲食文化。活動同時舉辦「115年苗栗市特色伴手禮徵件活動」頒獎典禮，總獎金新臺幣11萬元，頒發金、銀、銅獎及佳作多項，並透過線上人氣票選選出貓裏人氣獎。", "sample": false, "url": "https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=1007509"}, {"id": "https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=1007507", "title": "「客庄美饌 巧廚盛宴」縣長鍾東錦邀民眾品嚐客家好味緒、感受苗栗客庄魅力", "date": "2026-10-25", "category": "客庄新聞", "unit": "苗栗縣", "summary": "苗栗市公所於10月25日下午在苗栗市貓裏喵親子公園旁舉辦「客庄美饌·巧廚盛宴」客家風味宴，開設147桌，吸引近2,000位民眾參與。縣長鍾東錦與文化觀光局副局長謝國昌、議員鄭碧玉等各界代表出席，並邀請115年苗栗市青年歌唱舞蹈大賽得獎者演出。活動以十二道客家料理為主，並說明此為「2026苗栗風箏節暨客家美食節」系列之一，風箏節因颱風延期至11月6日至8日舉行。", "sample": false, "url": "https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=1007507"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=2c8a08f8-620b-40b9-8aa3-f8477f9d4752", "title": "臺北客家義民嘉年華登場 古主委：讓義民精神在當代持續傳承", "date": "2026-10-25", "category": "節慶活動", "unit": "客家委員會全球資訊網", "summary": "客家委員會主任委員古秀妃於10月25日上午出席2026臺北客家義民嘉年華主祭大典，與台北市長蔣萬安及各地義民廟、海內外客家社團代表共同祭拜義民爺。古主委呼籲全民守護民主、捍衛台灣，將義民精神傳承至新時代。嘉年華原訂10月24日至26日在中正紀念堂國家兩廳院藝文廣場舉行，因颱風影響改於10月25日移至台北市客家文化主題公園，並邀請全台23尊義民爺、忠勇公參與安座與主祭大典。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=2c8a08f8-620b-40b9-8aa3-f8477f9d4752"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=551546DCA635D526", "title": "「2026臺北客家義民嘉年華」 重返臺北客家「竇」，遵循古禮隆重登場！", "date": "2026-10-25", "category": "節慶活動", "unit": "臺北市", "summary": "臺北市政府客家事務委員會依循傳統古禮，在臺北市客家文化主題公園舉行安座大典及主祭大典，慶祝2026臺北客家義民嘉年華睽違7年重返。市長蔣萬安攜手客家後生YouTuber胡椒、臺大競技啦啦隊及臺北市民生國小師生等參與演出與百人大合唱。活動首次與臺北捷運合作點數兌換，兩天限量1萬個名額共發放10萬點。10月26日上午將舉行送神大典，為本屆嘉年華畫下句點。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=551546DCA635D526"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=2044902FC839D045&sms=72544237BBE4C5F6&s=A7BDF799C7312643", "title": "蔣萬安挑擔主祭臺北客家義民嘉年華 風雨無阻、敬意不減 傳承客家忠義精神", "date": "2026-10-25", "category": "節慶活動", "unit": "臺北市", "summary": "臺北市長蔣萬安於10月25日出席第38屆臺北客家義民嘉年華，與客家鄉親挑擔進場並擔任主祭官，祭拜義民爺。因颱風影響，活動原訂於二二八和平紀念公園改至臺北市客家文化主題公園舉行，規模與形式調整但敬意不減。市府推動客家文化走入生活，客家文化主題公園去年入園人次突破160萬，並於今年7月揭牌「客聚Taipei Hakka Hub」提供青年創作空間，持續深化客語與國際交流。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=2044902FC839D045&sms=72544237BBE4C5F6&s=A7BDF799C7312643"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=F8B2A291D8D13053", "title": "「2026臺北客家義民嘉年華」採訪通知", "date": "2026-10-24", "category": "節慶活動", "unit": "臺北市", "summary": "「2026臺北客家義民嘉年華」因應薔琵颱風路徑與外圍環流影響，為顧及市民及參與團體安全，10月25日移師臺北市客家文化主題公園辦理，場地與規模雖有異動，仍依古禮舉行義民祭典。當天上午10時進行「安座大典」，恭請全臺各地義民爺及忠勇公駐駕臺北；上午11時由市長蔣萬安與活動代言人、客家後生YouTuber胡椒及臺北客家鄉親代表挑擔進入主會場，進行「主祭大典」。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=F8B2A291D8D13053"}, {"id": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26813&s=8843426", "title": "臺南市政府客家事務委員會-筆尖上的神韻！ 「百媚千嬌」2026悠遊畫會人物寫生創作成果展精彩登場", "date": "2026-10-24", "category": "客家文化", "unit": "臺南市", "summary": "社團法人台南市客家文化協會與臺南市悠遊畫會於10月24日上午10點在臺南市客家文化會館舉辦「百媚千嬌」2026悠遊畫會人物寫生創作成果展開幕。市長黃偉哲邀請藝文愛好者及市民前往觀展。展出近60幅油畫、水彩、粉彩等人物寫生作品，展期自即日起至11月28日止，開放時間為每週二至週日上午9時至下午5時。", "sample": false, "url": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26813&s=8843426"}, {"id": "https://nghr.gov.taipei/News_Content.aspx?n=7F41B0B768E381AE&sms=78D644F2755ACCAA&s=1720137AD7941EDD", "title": "【2026臺北客家義民嘉年華】場地更換及流程更改公告", "date": "2026-10-24", "category": "節慶活動", "unit": "臺北市", "summary": "臺北市政府客家事務委員會因颱風影響，將2026臺北客家義民嘉年華全部改在臺北市客家文化主題公園舉辦，並取消客語兒歌比賽、青年美食決賽、客家行動劇、小禾埕市集及親子系列周邊活動，其他祭典與核心活動仍照常進行，請持續關注最新公告。", "sample": false, "url": "https://nghr.gov.taipei/News_Content.aspx?n=7F41B0B768E381AE&sms=78D644F2755ACCAA&s=1720137AD7941EDD"}, {"id": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&sms=10313&s=1007450", "title": "【2026客庄美饌・巧廚盛宴｜桌次查詢暨報到提醒】", "date": "2026-10-22", "category": "客庄新聞", "unit": "苗栗市公所", "summary": "苗栗市公所提醒，預訂「2026客庄美饌・巧廚盛宴」客家風味晚宴的民眾，活動於10月25日（星期日）在貓裏喵親子公園舉行，16:30至17:00報到、17:00開席。請先以「訂桌人姓名＋電話後四碼」查詢桌號並轉告同桌親友，當天到對應的報到帳篷核對後領取桌卡入座，並預留交通與停車時間。", "sample": false, "url": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&sms=10313&s=1007450"}, {"id": "https://doit.gov.taipei/News_Content.aspx?n=E3D88B653EACBF6E&sms=78D644F2755ACCAA&s=70F651B57B17A870", "title": "本府消息-2026臺北客家義民嘉年華活動因應薔琵颱風方案公告", "date": "2026-10-22", "category": "節慶活動", "unit": "臺北市", "summary": "因應薔琵颱風可能來襲，2026臺北客家義民嘉年華調整方案：10月24日（六）全日活動取消，原訂當天上午的迎神安座祭典併入10月25日（日）上午辦理；25日、26日活動維持，挑擔踩街啟動及集結地點改在弘道國中；原訂10月23日領取香案供品取消，改由主辦單位直接送至主會場。主辦單位提醒民眾自備輕便雨衣、雨具與替換衣物，注意安全及保暖。", "sample": false, "url": "https://doit.gov.taipei/News_Content.aspx?n=E3D88B653EACBF6E&sms=78D644F2755ACCAA&s=70F651B57B17A870"}, {"id": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=2bdd732e178bafed828687aca88f3a8c", "title": "市政新聞-新北客家躍上國際！「快閃客」奪美國MUSE金銀雙獎青年展豐沛創意客家文化品牌再添國際亮點", "date": "2026-10-21", "category": "客家文化", "unit": "新北市", "summary": "新北市政府客家事務局114年客家文化體驗活動「快閃客」的視覺設計，榮獲2026美國繆思創意獎（MUSE Creative Awards）文字排印類海報金獎與文字排印應用銀獎。局長劉冠吟10月21日率團隊於市政會議獻獎予市長侯友宜。作品由客家青年智庫團成員李懿宸設計，以「文化走進城市、城市遇見客家」為核心概念，結合金屬質感、客家藍與茶湯色，重新詮釋客家文化品牌。", "sample": false, "url": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=2bdd732e178bafed828687aca88f3a8c", "topic": "產業報導"}, {"id": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&s=1006579", "title": "🍽️ 2026客庄美饌・巧廚盛宴｜活動照常舉行暨交通管制公告 🚧", "date": "2026-10-21", "category": "客庄新聞", "unit": "苗栗市公所", "summary": "苗栗市公所公告，「2026客庄美饌・巧廚盛宴」雖受颱風影響，目前仍照常舉行，訂於10月25日（星期日）16:30入席、17:00開席。為配合場地布置與活動進行，10月24日0時至10月25日23時59分封閉貓裏喵親子公園前舊道（玉清路至育英街53巷路段），請用路人提前規劃路線，民眾出門前留意天氣與後續公告並做好防雨準備。", "sample": false, "url": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&s=1006579"}, {"id": "https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=1006484", "title": "苗栗2026風箏文化暨客家美食節活動記者會", "date": "2026-10-21", "category": "客家文化", "unit": "苗栗縣", "summary": "苗栗2026風箏文化暨客家美食節記者會10月21日在苗栗河濱公園舉行，副縣長邱俐俐表示今年把客家粄粽做成風箏。原訂10月24日至26日的風箏節因颱風延期至11月6日至8日舉辦，6日晚間揭幕並有夜光風箏展演；「客家美饌 巧廚盛宴」則如期於10月25日（星期日）下午5時開席。現場另有美食嘉年華與菁市集，購買200元消費券可兌換限量紀念風箏，消費券也能在美食區折抵。", "sample": false, "url": "https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=1006484"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&s=BE62A5C62542F440", "title": "一針一線將客家文學縫進衣服裡！2026客家時尚獎服飾展重磅登場", "date": "2026-10-21", "category": "客家文化", "unit": "臺北市", "summary": "臺北市政府客家事務委員會與台北市客家文化基金會主辦的「客家時尚獎服飾展」即日起於客家文化主題公園展至11月25日，延續2026客家時尚獎競賽精神，以永續文學為策展核心。121組報名中30組進決賽，11組得獎設計展出。10月1日至11月1日響應臺北時裝週，10月24日至25日進駐兩廳院藝文廣場，11月6日至25日移師客家文化中心5樓百坪展覽館接力展出，12月份亦規劃於桃園機場進行展示。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&s=BE62A5C62542F440"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=74806083EBDF5A03&sms=72544237BBE4C5F6&s=C354CFDAD9729EBC", "title": "臺北市客家文化主題公園植栽褐根病防治作業說明", "date": "2026-10-21", "category": "客家文化", "unit": "臺北市", "summary": "台北市客家文化基金會說明，114年例行巡檢時發現臺北市客家文化主題公園約350平方公尺的原始林相區域多株樹木異狀，經專業廠商勘察及農業部林試所檢驗，確認感染褐根病，已陸續進行防治並設置告示與解說牌，預計115年11月30日完工。為確保民眾安全將移除罹病樹木，未來將新增小型水池、新植原生種喬木，朝兼具生態、綠蔭與公共安全的都市森林復育。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=74806083EBDF5A03&sms=72544237BBE4C5F6&s=C354CFDAD9729EBC"}, {"id": "https://www.north.taichung.gov.tw/4080012/post", "title": "最新消息-轉知-臺中市政府客家事務委員會【2026臺中市舞客神曲大賽】徵件中!!", "date": "2026-10-20", "category": "客家文化", "unit": "臺中市", "summary": "臺中市政府客家事務委員會舉辦「2026臺中市舞客神曲大賽」，參賽者需選用指定客家舞曲《勞瀝》或《來台中尞》自行編舞，錄製60秒影片參賽。最高獎金3萬元，分為學生組與社會組，每隊需3人以上。報名及影片寄送至指定信箱，徵件即日起至2026年11月6日中午12點截止。洽詢電話(04)2523-0059，聯絡人曾小姐。", "sample": false, "url": "https://www.north.taichung.gov.tw/4080012/post"}, {"id": "https://www.mlcg.gov.tw/News_Content.aspx?n=2546&s=1006063", "title": "2026貓裏客庄・好食好聲音", "date": "2026-10-20", "category": "客庄新聞", "unit": "苗栗市公所", "summary": "苗栗市公所於10月26日舉辦「2026貓裏客家粄食文化節」與「2026苗栗客家歌手演唱會」，分別在貓裏喵親子公園與苗栗巨蛋體育館，免費開放民眾參與，結合客家飲食、音樂與在地藝文，推廣客家文化與觀光。", "sample": false, "url": "https://www.mlcg.gov.tw/News_Content.aspx?n=2546&s=1006063"}, {"id": "https://hk.hl.gov.tw/News_Content.aspx?n=10188&sms=15469&s=232627", "title": "花蓮不只玩山海！走進客庄輕旅行：九大客庄行程地圖", "date": "2026-10-20", "category": "客庄新聞", "unit": "花蓮縣", "summary": "本處推出《走進客庄輕旅行》摺頁地圖，串連新城鄉、花蓮市、吉安鄉、壽豐鄉、鳳林鎮、光復鄉、瑞穗鄉、玉里鎮、富里鄉九個客庄，規劃九條主題行程，讓旅人以輕鬆步調認識花蓮客家文化、人文風景與在地美食。", "sample": false, "url": "https://hk.hl.gov.tw/News_Content.aspx?n=10188&sms=15469&s=232627"}, {"id": "https://dot.gov.taipei/News_Content.aspx?n=D739A9F6B5C0AB95&sms=72544237BBE4C5F6&s=8453B1F17FDAD6C4", "title": "新聞稿-因應「2026臺北客家義民嘉年華」活動交通管制，公車配合調整措施", "date": "2026-10-20", "category": "節慶活動", "unit": "臺北市", "summary": "臺北市公共運輸處因應10月24、25日舉辦的2026臺北客家義民嘉年華，於每日8時至11時管制汀州路、辛亥路、羅斯福路及中山南路等路段，預計有11條市區公車改道並取消6處站位，相關資訊將於公車網站、APP及智慧站牌同步顯示，民眾可撥1999或至調度站詢問。", "sample": false, "url": "https://dot.gov.taipei/News_Content.aspx?n=D739A9F6B5C0AB95&sms=72544237BBE4C5F6&s=8453B1F17FDAD6C4"}, {"id": "https://doit.gov.taipei/News_Content.aspx?n=E3D88B653EACBF6E&sms=78D644F2755ACCAA&s=B878D3D69D68C03F", "title": "本府消息-2026 臺北客家義民嘉年華「義鳴紀」-因應薔琵颱風活動公告", "date": "2026-10-20", "category": "節慶活動", "unit": "臺北市", "summary": "因應強颱薔琵可能來襲，臺北市客委會針對10月24日至26日舉辦的2026臺北客家義民嘉年華「義鳴紀」召開緊急應變會議。依目前預報，10月24日（六）迎神活動暫維持正常辦理、風雨無阻，請民眾自備輕便雨衣，現場不搭遮雨棚。若人事行政總處宣布24日停班停課，則取消當日迎神遶境遊行，迎神及安座大典延至25日（日）合併舉行，沿途79處香案改集中設於兩廳院圓形帳篷供品區。", "sample": false, "url": "https://doit.gov.taipei/News_Content.aspx?n=E3D88B653EACBF6E&sms=78D644F2755ACCAA&s=B878D3D69D68C03F"}, {"id": "https://www.taichung.gov.tw/8868/8872/9971/3395063", "title": "2026臺中客家跨世代對話【客家个來時路同下一步】活動開放報名中", "date": "2026-10-19", "category": "客家文化", "unit": "臺中市", "summary": "臺中市政府客家事務委員會將於11月12日（四）國父誕辰紀念日上午9:30至12:30，在豐原區憬初尋咖啡廳舉辦「客家跨世代對話」活動。上半場由羅肇錦教授以「國父與近代史的客家」為題演講，下半場邀請客家青年分享結合聯合國永續發展目標的在地實踐。活動全程免費，名額上限100名，額滿為止；無法出席請於活動前3日來電取消。洽詢：客委會黃先生，電話(04)2228-9111分機52203。", "sample": false, "url": "https://www.taichung.gov.tw/8868/8872/9971/3395063"}, {"id": "https://www.hl.gov.tw/News_Content.aspx?n=32725&s=232596", "title": "花蓮縣舉辦主流化論壇暨客家文化風華獎頒獎 表揚11位文化推手 共探客家永續與創新", "date": "2026-10-19", "category": "產業與觀光", "unit": "花蓮縣", "summary": "花蓮縣政府於115年舉辦主流化論壇暨客家文化風華獎頒獎典禮，邀請產官學界代表與客家文化工作者交流，聚焦AI與客家產業結合，表揚包括呂嵩雁教授在內的11位在語言、藝術、校園推廣、社區營造及地方產業等領域的貢獻者。", "sample": false, "url": "https://www.hl.gov.tw/News_Content.aspx?n=32725&s=232596"}, {"id": "https://www.hakka.tycg.gov.tw/News_Content.aspx?n=11504&s=1908972", "title": "桃園市政府115學年度國小及國中客語沉浸式教學設計評選計畫", "date": "2026-10-19", "category": "客語推廣", "unit": "桃園市", "summary": "桃園市政府客家事務局與教育局合辦115學年度國小及國中客語沉浸式教學設計評選，對象為本學年度獲客家委員會補助推動客語沉浸式教學的市內國中小教學團隊（每組2至5人），設計2至4節單元課程，客語使用至少達50%。即日起至115年12月31日止郵寄或親送客家局，特優獎10,000元禮券、優等獎8,000元、佳作6,000元，預定116年4月1日前公告結果。", "sample": false, "url": "https://www.hakka.tycg.gov.tw/News_Content.aspx?n=11504&s=1908972"}, {"id": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8842346", "title": "東南地政走入客家藝術節 解碼車位產權與不動產防詐", "date": "2026-10-18", "category": "客家文化", "unit": "臺南市", "summary": "臺南市政府地政局與東南地政事務所在10月17日舉辦的2026臺南客家藝術節現場設攤，向民眾宣導車位產權與不動產防詐資訊，並示範「府城南籍圈」查詢實價登錄，提醒購屋前釐清車位權利與價格，提供免費申請「地籍與稅籍異動即時通」服務。", "sample": false, "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8842346"}, {"id": "https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=1005354", "title": "「大人細子鬧熱打嘴鼓比賽」熱鬧登場 親子共下講客 傳承客家語言文化", "date": "2026-10-18", "category": "客語推廣", "unit": "苗栗縣", "summary": "苗栗縣政府18日在縣府第一辦公大樓舉辦「2026苗栗縣大人細子鬧熱打嘴鼓比賽」，副縣長賴香伶出席頒獎。比賽已連續第三年辦理，以親子日常客語對話為主軸，分幼兒及國小低年級組、國小中高年級組兩大類，共47組親子家庭參賽，總獎金37萬2千元，盼讓客語走入家庭、向下扎根。", "sample": false, "url": "https://www.miaoli.gov.tw/News_Content2.aspx?n=285&s=1005354"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=dfe51be7-cb1d-46e2-9a96-3891e10abf56", "title": "跨世代、跨族群齊講客 115年客語家庭表揚南區登場", "date": "2026-10-18", "category": "客語推廣", "unit": "客家委員會全球資訊網", "summary": "客家委員會主任委員古秀妃於10月18日前往屏東內埔鄉六堆客家文化園區，出席115年度客語家庭表揚典禮南區場。典禮表揚549戶、逾1,600位成員，其中約80戶到場，並每位受表揚成員發給1,000元客家幣，鼓勵家庭與社區使用客語。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=dfe51be7-cb1d-46e2-9a96-3891e10abf56"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=92023252-79a1-4eef-a590-9047f4f98ff5", "title": "龍潭七十三公忠義廟秋祭 追思先烈傳承客家忠義精神", "date": "2026-10-18", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "客家委員會主任秘書吳克能於10月18日代表古秀妃主委，出席桃園市龍潭區七十三公忠義廟舉辦的秋祭大典。祭典由桃園市七十三公忠義協會籌辦，邀請立法委員呂玉玲、桃園市政府客家事務局副局長饒佳汶等多位官員及後裔代表參與，並以客家古禮舉行三獻禮，安排客家排舞、鼓陣、健康舞、歌謠與獅陣等藝文表演，旨在追思乙未戰役中犧牲的73位先烈，傳承客家忠義精神。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=92023252-79a1-4eef-a590-9047f4f98ff5"}, {"id": "https://www.cna.com.tw/news/aloc/202610180098.aspx", "title": "高雄秋季觀光活動　單車遊、鹹酥雞嘉年華陸續登場", "date": "2026-10-18", "category": "產業與觀光", "unit": "中央社", "summary": "高雄市政府觀光局於10月18日舉辦「2026高雄單車自遊行」三民場，規劃約8公里路線，串聯新客家文化園區，並於10月24、25日舉辦「2026高雄鹹酥雞嘉年華」聚集全臺88家美食品牌，11月7、8日推出「2026高雄Wild Wild野生活」露營與親子體驗，活動同時推出「99重陽」長者騎乘加碼。", "sample": false, "url": "https://www.cna.com.tw/news/aloc/202610180098.aspx"}, {"id": "https://www.cna.com.tw/news/acul/202610180136.aspx", "title": "屏東客家歌謠傳情八音共鳴6班隊展現傳習成果", "date": "2026-10-18", "category": "客家文化", "unit": "中央社", "summary": "屏東縣政府於10月18日在客家文化中心舉辦「歌謠傳情八音共鳴」成果展演，展示客家文藝研習計畫一年來的6組音樂班隊學習成果，包含六堆山歌、八音及跨世代融合演出，並由客家事務處長謝俊明鼓勵將所學帶回社區持續傳承。", "sample": false, "url": "https://www.cna.com.tw/news/acul/202610180136.aspx"}, {"id": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26840&s=8842351", "title": "臺南市政府客家事務委員會-共下共好！ 楠西創生成果串起臺日交流市民共賞客底文化活力", "date": "2026-10-18", "category": "客家文化", "unit": "臺南市", "summary": "臺南市政府客家事務委員會攜手國立高雄科技大學，18日在臺南市客家文化會館舉辦「共下．共好」楠西駐地工作站成果展暨特色產業展售活動，有成果展、特色市集、手作體驗及客華雙語繪本導讀，並邀日本笠間台灣辦事處坪井勇樹處長分享地方創生經驗。臺南市客委會主委陳新裕表示，楠西工作站已促成相關計畫獲文化部、教育部及農業部等補助達200萬餘元。", "sample": false, "url": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26840&s=8842351", "topic": "產業報導"}, {"id": "https://www.taitung.gov.tw/News_Content.aspx?n=14600&s=150107", "title": "客家藝文競賽東區初賽臺東登場 逾500師生以藝傳客.體驗關山文化", "date": "2026-10-17", "category": "客家文化", "unit": "臺東縣", "summary": "客家委員會指導、臺東縣政府主辦的115年全國中小學客家藝文競賽東區初賽，10月17日在關山國小登場。宜蘭、花蓮、臺東共22校38隊逾500師生參與，341名學生分客語歌唱、戲劇、口說藝術類競賽。賽事外安排關山天后宮導覽及客家花布貓頭鷹DIY、牛汶水點心體驗，讓客語學習貼近在地文化。", "sample": false, "url": "https://www.taitung.gov.tw/News_Content.aspx?n=14600&s=150107"}, {"id": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8842316", "title": "黃偉哲推廣多元族群文化 台南客家藝術節野台大戲《天緣記》登場", "date": "2026-10-17", "category": "客家文化", "unit": "臺南市", "summary": "台南客家藝術節10月17日在水萍塭公園登場，今年以「多元族群嘉年華」為主題，串聯客家、新住民及原住民族文化，安排市集、DIY體驗、IP互動及舞台演出，市長黃偉哲出席。客委會特別以野台戲形式演出榮興客家採茶劇團《天緣記》，重現客庄農忙後看「收冬戲」的傳統，讓民眾不必進劇場就能在公園近距離欣賞客家戲曲。", "sample": false, "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8842316"}, {"id": "https://www.taichung.gov.tw/8868/8872/9962/3394193", "title": "弦歌共譜客家情！大里客家音樂會秋夜開唱連辦10年", "date": "2026-10-17", "category": "客家文化", "unit": "臺中市", "summary": "台中市政府客家事務委員會協助大里區公所於10月16日晚在大里區美群國小舉辦「115 年客家音樂會～美韻．弦歌共築客家情」，邀請客語創作歌手、校園團隊與公益樂團，以音樂、舞蹈、相聲等多元形式呈現客家文化，吸引市民參與，並由多位官員與教育界代表共襄盛舉，促進客家文化永續發展。", "sample": false, "url": "https://www.taichung.gov.tw/8868/8872/9962/3394193"}, {"id": "https://www.klcg.gov.tw/tw/development/2631-323641.html", "title": "基隆客家同鄉會歡慶重陽 邱佩琳盼敬老傳承凝聚世代力量 讓幸福在基隆延續", "date": "2026-10-17", "category": "客家文化", "unit": "基隆市", "summary": "基隆市客家同鄉會於10月17日重陽節前夕舉辦115年「敬老重陽 幸福相伴」活動，表揚44位年滿80歲以上的客家長輩。副市長邱佩琳代表市長謝國樑率市府團隊出席致意，長輩佩戴專屬敬老帽展現樂活風采。邱佩琳肯定客家人勤儉堅毅精神，並說明基隆老年人口比例達22.6%，市府推動高齡友善與全齡照護，讓長者持續參與社會發揮所長。", "sample": false, "url": "https://www.klcg.gov.tw/tw/development/2631-323641.html"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=7d5a93d2-05cc-4942-85f2-106f2a575477", "title": "全國中小學客家藝文競賽南、東區初賽登場 逾千名師生「藝」起傳客", "date": "2026-10-17", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "客委會與屏東縣、臺東縣政府10月17日分別在美和科技大學及關山國小、關山國中舉辦115年全國中小學客家藝文競賽南區、東區初賽，共8縣市、83所學校、133隊、1,139人參加，比賽客語歌唱、口說藝術及戲劇等項目。獲特優的30所學校將於12月5日到新生醫護管理專科學校參加全國總決賽。今年符合資格的參賽師生每人另可獲500元客家幣。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=7d5a93d2-05cc-4942-85f2-106f2a575477"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&s=0A1871D975BAAD52", "title": "15位客家青年大使立足臺北邁向國際！", "date": "2026-10-17", "category": "客家文化", "unit": "臺北市", "summary": "臺北市客委會指導、台北市客家文化基金會主辦的「臺北客家全球串流計畫」邁入第12年，10月17日在客聚舉行成果發表會。今年首度與教育部青年發展署合作，15位客家青年大使前往新加坡、雅加達與山口洋尋根並創作。成果展10月29日前免費開放，分別在客聚5樓及汀州路客家文化中心1樓，週一休館，完成集點問卷可換紀念品。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&s=0A1871D975BAAD52"}, {"id": "https://thcdc.hakka.gov.tw/12205/12214/12215/172617/post", "title": "「客庄食茶-茶米入席好味緒」", "date": "2026-10-17", "category": "產業與觀光", "unit": "客家委員會客家文化發展中心", "summary": "客委會客家文化發展中心10月17日首度在苗栗銅鑼臺灣客家文化館舉辦「客庄食茶-茶米入席好味緒」茶席體驗，由茶藝師沖泡高山青茶、貓裏紅茶及東方美人茶，搭配南瓜粄、發粄等客家粄食，另有客語歌曲演出、茶香米食市集及粄食DIY。客發中心也邀請民眾11月銅鑼杭菊季期間，前往參觀與故宮合作的「眾神降臨-敬天惜地的客家人特展」，展出國寶「三官出巡圖」。", "sample": false, "url": "https://thcdc.hakka.gov.tw/12205/12214/12215/172617/post"}, {"id": "https://culture.tycg.gov.tw/News_Content.aspx?n=11099&s=1904543", "title": "2026客家精緻好戲——《樊梨花掛帥》震撼登場！", "date": "2026-10-17", "category": "客家文化", "unit": "桃園市", "summary": "德泰劇團將於11月7日（星期六）晚間7時在桃園市政府演藝廳（桃園市桃園區縣府路21號）演出年度客家戲曲大戲《樊梨花掛帥》，由傳承演員李品蓉、黃鈺翔、朱晉陞、朱信逸、朱亭羽領銜，展現青年演員為傳統客家戲曲注入的新生命。演出免費入場，歡迎民眾邀家中長輩與親友共下來看戲。", "sample": false, "url": "https://culture.tycg.gov.tw/News_Content.aspx?n=11099&s=1904543"}, {"id": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=99b9a36ef6534566ff6b416850d6b0e1", "title": "市政新聞-陸羽盃265人競技「客來酵」跨文化新食力康普酸柑茶、天貝料理結合AI設計客家飲食與國際接軌", "date": "2026-10-16", "category": "客家文化", "unit": "新北市", "summary": "宏國德霖科技大學與新北市政府客家事務局合辦的「2026陸羽盃客家茶飲暨茶餐料理競賽」10月15日登場，今年邁入第11年，有29校、265名國中至大專學生參賽。競賽以食當季、吃在地、剩食創新為主題，綠色餐飲海報設計首度融入生成式AI。現場同步舉行「客來酵開懷」成果展，從酸柑茶延伸到康普茶，並引入印尼發酵食品天貝，與客家桔醬、紅糟結合成跨文化料理。", "sample": false, "url": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=99b9a36ef6534566ff6b416850d6b0e1"}, {"id": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&sms=10313&s=1005314", "title": "【客語認證培訓課程｜開課提醒】", "date": "2026-10-16", "category": "客語推廣", "unit": "苗栗市公所", "summary": "苗栗市公所115年客語認證培訓課程即將開課，提醒已錄取學員留意時間。初級班10月20日起每週二、四晚上7點至9點上課，中級班10月21日起每週三、五同時段上課，10月31日、11月7日及14日週六另有加開課程。地點在苗栗生活美學中心（建功社區活動中心二樓），首堂簽到贈200元禮券，全勤再贈300元。課程洽詢0970-893-190。", "sample": false, "url": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&sms=10313&s=1005314"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=cece38e5-feac-4087-9b3b-e3fc68d31dd0", "title": "本會辦理第1次專案公告受理「2027客家流行音樂介入主流推廣合作補助計畫」", "date": "2026-10-16", "category": "政策與補助", "unit": "客家委員會全球資訊網", "summary": "客家委員會受理「2027客家流行音樂介入主流推廣合作補助計畫」第1次專案申請，即日起至115年11月20日止，一律線上申請。補助對象為具辦理大型音樂活動經驗的公司、財團法人或大專院校，每案原則上限新臺幣150萬元，全案預算2,000萬元，採書面審查。申請時須附公職人員及關係人身分關係事前揭露表。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=cece38e5-feac-4087-9b3b-e3fc68d31dd0"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=14cedce7-56bc-4580-adc6-fdc54520d3a0", "title": "「客家影像畢業製作孵育計畫徵選」 公布入選名單", "date": "2026-10-16", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "客家委員會公布首屆「客家影像畢業製作孵育計畫徵選」結果，15件報名作品經初審及9月28日複審，選出7件企劃書，每案最高可獲新臺幣50萬元輔導金，支持學生團隊完成畢業製作。入選作品來自臺藝大、聯合大學、世新、政大等校，涵蓋劇情片與紀錄片，題材包括家庭與女性經驗、返鄉遷徙、客庄飲食記憶與地方信仰。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=14cedce7-56bc-4580-adc6-fdc54520d3a0"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=epaper&id=21&serno=b2e53865-1652-465f-bc2e-a6cad44b080f", "title": "第958期│新北客家義民祭熱鬧登場", "date": "2026-10-16", "category": "節慶活動", "unit": "客家委員會全球資訊網", "summary": "客家委員會第958期電子報報導，「115年新北市客家義民爺文化祭」10月11日舉行挑擔奉飯創意踩街，估計3,000至4,000名客屬社團成員及鄉親從板橋第二運動場走到新北市民廣場。客委會主委古秀妃擔任主祭官，並表示客委會將自116年起開放都市地區申請設置伯公照護站，回應都市客家長者的照顧需求。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=epaper&id=21&serno=b2e53865-1652-465f-bc2e-a6cad44b080f"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=20280F8DCDBE44FF", "title": "「城客・來坐」客家紀錄片計畫圓滿落幕！", "date": "2026-10-16", "category": "客家文化", "unit": "臺北市", "summary": "臺北市政府客家事務委員會指導、台北市客家文化基金會主辦的「2026客家紀錄片製作計畫－城客・來坐」已圓滿落幕。計畫推出《南機場的皺摺》、《菜包的滋味》、《西餐盤裡的叛逆與韌性》三部紀錄片，10月3日首映與4日加映共吸引逾180人參與，並辦理5場工作坊、6場校園巡迴放映、8集Podcast專訪，以及10月4日至11日的線上影展。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=20280F8DCDBE44FF"}, {"id": "https://www.cna.com.tw/news/ahel/202610160136.aspx", "title": "客委會攜手紙風車推客語親子劇「燈怪」 台中將連演3晚", "date": "2026-10-16", "category": "客語推廣", "unit": "中央社", "summary": "客家委員會與紙風車劇團合作的原創客家親子劇「燈怪」，10月16日起一連3晚在台中大里區振坤宮幸福廣場演出，以華語、客語雙語呈現，現場有高達8公尺的巨型機械「燈燈國王」。客委會副主委廖育珮表示，這齣戲已巡演8個縣市、累積超過11萬名觀眾；每場演出前另有「唱瓜瓜歌送小燈怪」活動，歡迎中部民眾到場看戲。", "sample": false, "url": "https://www.cna.com.tw/news/ahel/202610160136.aspx"}, {"id": "https://www.chcg.gov.tw/ch2/newsdetail.aspx?bull_id=439903&utm_source=website&utm_medium=list&utm_campaign=news01", "title": "彰化縣三山國王客底文化節 10/24-25 同遊溪州‧花香客庄", "date": "2026-10-16", "category": "客庄新聞", "unit": "彰化縣", "summary": "「2026彰化縣三山國王客底文化節」將於10月24、25日在溪州鄉三千宮舉行，由彰化縣三山國王客家文化協會主辦，集結全縣39間宮廟、117尊三山國王神尊，舉辦百神齊聚朝聖大典與火把夜巡遶境祈福。現場另有客家藝文展演、客庄走讀小旅行、客家美食DIY及農特產市集，縣府歡迎全國民眾前往體驗彰化福佬客文化。", "sample": false, "url": "https://www.chcg.gov.tw/ch2/newsdetail.aspx?bull_id=439903&utm_source=website&utm_medium=list&utm_campaign=news01"}, {"id": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&s=1004971", "title": "2026客庄美饌・巧廚盛宴｜辦桌報名暨交通管制公告", "date": "2026-10-15", "category": "客庄新聞", "unit": "苗栗市公所", "summary": "苗栗市公所舉辦「2026客庄美饌・巧廚盛宴」客家辦桌活動，即日起開放民眾線上報名，名額有限。為配合場地布置與活動進行，10月24日0時至10月25日23時59分將封閉貓裏喵親子公園前舊道（玉清路至育英街53巷路段），公所提醒用路人提前規劃行車路線。洽詢電話037-331910分機129。", "sample": false, "url": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&s=1004971"}, {"id": "https://www.hchcc.gov.tw/Tw/News/NewsDetail?filter=093437eb-1b2b-4130-9f8e-bf4218dfd22f&id=a40f9321-a636-40fa-aac0-e312a3d48b10", "title": "轉知「青銀共融走讀客庄」活動", "date": "2026-10-15", "category": "客庄新聞", "unit": "新竹縣政府文化局", "summary": "新竹縣推動伯公照護站青銀共融計畫，將於10月24日及25日在湖口鄉湖南社區舉辦「青銀共融走讀客庄」，由大專青年協力帶領民眾走訪故事牆、畚箕窩溪及八角樓，並有紙漿工藝與親子創意體驗。每場限30人，親子同行優先，報名至10月16日下午5時截止，10月19日以電子郵件通知錄取。全程步行，請評估體力後報名。", "sample": false, "url": "https://www.hchcc.gov.tw/Tw/News/NewsDetail?filter=093437eb-1b2b-4130-9f8e-bf4218dfd22f&id=a40f9321-a636-40fa-aac0-e312a3d48b10"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=c8f6c941-77c0-43b5-99cf-53ccbcb4eeb8", "title": "客家影視音金鐘入圍37項 客委會辦交流會致敬創作者", "date": "2026-10-15", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "客委會10月15日在台北舉辦第61屆金鐘獎客家入圍交流會，副主委廖育珮代表致意，表示將持續支持客家影視音創作。今年客家作品共16件入圍37項，其中《客家電影院－屋下無人》入圍8項、《都市開基祖》入圍7項、《客家電影院－小包袱》入圍5項；廣播節目也有9件作品入圍11項。現場並有林生祥演唱《都市開基祖》主題曲。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=c8f6c941-77c0-43b5-99cf-53ccbcb4eeb8"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=c188a982-8470-41b3-9773-27f3d7fb2ce9", "title": "客委會力挺卓蘭鎮立圖書館重建 打造卓蘭最亮眼的文化珍珠", "date": "2026-10-15", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "客委會主委古秀妃10月15日陪同立委沈發惠現勘苗栗縣卓蘭鎮立圖書館。該館啟用約35年，經耐震評估補強效益不佳，加上滲水與空間擁擠，決定拆除重建。計畫總經費約1億4,560萬餘元，客委會補助卓蘭鎮公所9,900萬元，將整合周邊日式建築與展示空間，並與詹冰文學故事館、卓蘭國小串聯，成為在地客家語言文化推廣據點。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=c188a982-8470-41b3-9773-27f3d7fb2ce9"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=8cd86169-f430-4ca4-8bb3-22784975a53c", "title": "客家幣2.0校園資訊彙整雙軌併行 明年3月推出「個人線上申請機制」", "date": "2026-10-15", "category": "政策與補助", "unit": "客家委員會全球資訊網", "summary": "針對教師團體反映「客家幣2.0校園獎勵計畫」增加學校行政負擔，客委會10月15日致歉並調整作法，明年3月將推出「個人線上申請機制」，學校可選擇繼續批次協助，或由師生自行上網申請，雙軌併行。11月30日前完成校園資訊彙整平臺填報的師生，今年12月即可使用客家幣。客委會預定10月28日召開記者會說明相關作業。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=8cd86169-f430-4ca4-8bb3-22784975a53c"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=035DDAAA34A9BB61", "title": "百萬網紅「胡椒」背電吉他潮味登場！ 2026臺北客家義民嘉年華「義鳴紀」10/24盛大開跑", "date": "2026-10-15", "category": "節慶活動", "unit": "臺北市", "summary": "「2026臺北客家義民嘉年華」以「義鳴紀」為主題，將於10月24日至26日在中正紀念堂兩廳院藝文廣場舉行，由客家YouTuber胡椒擔任代言人。24日有全臺23尊義民爺及忠勇公齊聚臺北，進行2.4公里遶境；25日有挑擔踩街並首度開放民眾帶毛小孩參加。現場另有AR互動兌換北捷點數、百攤市集與客家美食賽，詳情可查「臺北客家」粉絲專頁。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=035DDAAA34A9BB61"}, {"id": "https://www.cna.com.tw/news/aipl/202610150286.aspx", "title": "總統府17日開放參觀安排客家民謠樂團、吳永吉演出", "date": "2026-10-15", "category": "客家文化", "unit": "中央社", "summary": "總統府10月17日上午9時至下午4時開放民眾參觀，開放府前廣場、大禮堂、南北苑及1樓展場等區域。當天上午10時至11時由現代客家民謠樂團「好日HoNi」在大禮堂演出，下午2時至3時由董事長樂團主唱吳永吉表演。民眾須由寶慶路與博愛路管制哨進府並接受安檢，攝錄影機及大型背包不得攜入，現場備有置物櫃。", "sample": false, "url": "https://www.cna.com.tw/news/aipl/202610150286.aspx"}, {"id": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26813&sms=21558&s=8842086", "title": "從一片瓦看見客家文化記憶 臺南市族群主流化培力工作坊邀鍾心怡建築師分享老屋修復與傳統技藝傳承", "date": "2026-10-15", "category": "客家文化", "unit": "臺南市", "summary": "臺南市政府客家事務委員會10月15日在臺南市客家文化會館舉辦「115年臺南市族群主流化培力工作坊」，邀請曾獲客家貢獻獎的鍾心怡建築師，以「從一片瓦開始」為題，分享客家傳統建築、老屋修復與瓦作傳習經驗。參加者為市府局處、區公所同仁及志工，課程也將錄製成數位課程，上架公務人員線上學習平台「e等公務園」。", "sample": false, "url": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26813&sms=21558&s=8842086"}, {"id": "https://tcnm.taichung.gov.tw/565123/565140/565143/nodeCp?nodeId=3391475", "title": "台中客庄創生成績亮眼！跨域整合爭取5.2億資源 36項專案打造山城文化新亮點", "date": "2026-10-14", "category": "客庄新聞", "unit": "臺中市", "summary": "台中市政府客家事務委員會自108年以來整合地方提案，獲中央客家委員會核定36項專案，累計投入約5.2億元（中央補助逾4億、市府編列逾1億）。東勢客家文化園區二期復舊工程預計今年10月底動工；翁子公學校修復後將作為客語教學館與校史館；新社、石岡山城圖書分館改造可望年底完工。", "sample": false, "url": "https://tcnm.taichung.gov.tw/565123/565140/565143/nodeCp?nodeId=3391475", "topic": "產業報導"}, {"id": "https://www.mlcg.gov.tw/News_Content.aspx?n=2546&sms=10314&s=1003690", "title": "苗栗市客庄福麗健行步道再獲客委會700萬元補助 打造客庄文化與綠色休憩新亮點", "date": "2026-10-13", "category": "政策與補助", "unit": "苗栗市公所", "summary": "苗栗市公所「客庄福麗健行步道整體營造計畫工程施作案」獲客家委員會核定補助700萬元。福麗古道位於福麗里文麗福德祠旁，計畫整建約250公尺步道，含階梯、欄杆、休憩平台與入口停車場等。工程總經費933萬3,000元，其中市公所自籌233萬3,000元；前期規劃設計已獲補助101萬餘元。", "sample": false, "url": "https://www.mlcg.gov.tw/News_Content.aspx?n=2546&sms=10314&s=1003690"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=4fcea621-9aae-4ab4-84d8-8d728e3033b7", "title": "藍衫樂舞團首度訪菲 客家歌舞展現臺灣文化魅力", "date": "2026-10-13", "category": "客家文化", "unit": "客家委員會全球資訊網", "summary": "菲律賓臺灣客家聯誼會10月7日下午在馬尼拉中正學院大禮堂舉辦「客韻菲揚．國慶共榮」活動，來自六堆的藍衫樂舞團隨115年「臺灣豐華．六堆傳情」文化訪問團首度赴菲，以客家歌謠、傳統舞蹈與樂器演奏，吸引300餘位僑胞、華校師生及民眾參與。金鐘歌王康雷與二胡演奏家洪充惠也同台演出。樂舞團訪菲期間另參加僑界國慶活動，並於10月8日在駐菲代表處國慶酒會演出。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=4fcea621-9aae-4ab4-84d8-8d728e3033b7"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=17695bd1-f722-4113-9abf-5045c1ecba1a", "title": "范宸菲攜阿邱入圍廣播金鐘 《不專業逛超市》聊出客語味", "date": "2026-10-13", "category": "客語推廣", "unit": "客家委員會全球資訊網", "summary": "演員范宸菲與來自苗栗獅潭的阿邱共同主持的客語Podcast《不專業逛超市》，入圍第61屆廣播金鐘獎「播客生活風格節目獎」。節目從超市與傳統市場採買等生活話題出發，由客語學習者與母語使用者對談，並穿插華語，讓不熟悉客語的聽眾也能聽懂。客家委員會表示，以貼近生活的題材讓不同語言背景的民眾接觸客語，是推廣客家語言文化的重要方向。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=17695bd1-f722-4113-9abf-5045c1ecba1a"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=12AA11A4F84747ED", "title": "在雅加達尋找客家：當語言退潮，文化仍在城市深處延續？", "date": "2026-10-13", "category": "全球客家", "unit": "臺北市", "summary": "臺北市客委會10月13日起推出「2026全球客家串流－跨越南洋、青年同行、尋根客家」成果展，展出15位臺北客家青年赴印尼雅加達等地田野調查的影音、文字與創作，記錄當地客家文化在語言斷層下如何延續。展期至10月29日，在客聚（大安區復興南路二段230號5樓）與臺北市客家文化中心1樓沙龍免費參觀；10月17日（六）14時於客聚舉辦成果發表會，歡迎民眾參加。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&sms=72544237BBE4C5F6&s=12AA11A4F84747ED"}, {"id": "https://www.hchcc.gov.tw/Tw/News/NewsDetail?filter=093437eb-1b2b-4130-9f8e-bf4218dfd22f&id=2b7453d0-9e4a-42f5-9c67-e3079840e80b", "title": "客家委員會（下稱客委會）受理116年度「藝文團隊補助計畫」申請一案，歡迎藝文團隊踴躍申請", "date": "2026-10-12", "category": "政策與補助", "unit": "新竹縣政府文化局", "summary": "新竹縣政府文化局10月12日轉知，客家委員會受理116年度「藝文團隊補助計畫」申請，對象為依法登記、立案的音樂、戲劇及民俗技藝團隊。受理期間為115年10月1日至31日，須在客委會獎補助系統線上申辦，並於截止日前將相關文件1式10份寄交客委會。因116年度預算尚未審議通過，全案預算金額尚未確定，詳細規定可至客委會網站查詢。", "sample": false, "url": "https://www.hchcc.gov.tw/Tw/News/NewsDetail?filter=093437eb-1b2b-4130-9f8e-bf4218dfd22f&id=2b7453d0-9e4a-42f5-9c67-e3079840e80b"}, {"id": "https://www.doe.gov.taipei/News_Content.aspx?n=B3DDF0458F0FFC11&sms=72544237BBE4C5F6&s=413BBBBEACB6C383", "title": "萬興國小-芭蕉扇竟賣給手機妖精！景勝戲劇團客家戲劇融入反詐騙 培養學童媒體識讀力", "date": "2026-10-12", "category": "客家文化", "unit": "臺北市", "summary": "臺北市文山區萬興國小10月12日發布新聞稿，景勝戲劇團到校巡迴演出客家戲劇《悟空飛了之風起芭蕉扇》，以《西遊記》紅孩兒誤信網友、賣掉芭蕉扇的情節，結合網路詐騙議題，引導學生辨識網路訊息、防範詐騙、保護個人資料，有疑問時向家長或老師求助。這場演出由家長會引薦促成，適逢該校創校40週年。", "sample": false, "url": "https://www.doe.gov.taipei/News_Content.aspx?n=B3DDF0458F0FFC11&sms=72544237BBE4C5F6&s=413BBBBEACB6C383"}, {"id": "https://thcdc.hakka.gov.tw/12205/12214/12216/172335/post", "title": "「六堆客家文化園區遊客服務中心裝修」委託專業服務案", "date": "2026-10-12", "category": "客家文化", "unit": "客家委員會客家文化發展中心", "summary": "客家委員會客家文化發展中心10月12日公告招標「六堆客家文化園區遊客服務中心裝修」委託專業服務案（案號115062）。截標時間為10月19日下午5時，開標時間為10月20日上午10時。有意投標的廠商，請上政府電子採購網查詢招標資料並領標。", "sample": false, "url": "https://thcdc.hakka.gov.tw/12205/12214/12216/172335/post"}, {"id": "https://hk.hl.gov.tw/News_Content.aspx?n=10188&sms=15469&s=232132", "title": "新北市政府客家事務局文創商品店 116年商品寄賣徵件公告", "date": "2026-10-12", "category": "政策與補助", "unit": "花蓮縣", "summary": "花蓮縣政府客家事務處10月12日轉知，新北市政府客家事務局文創商品店公開徵求116年寄賣商品，歡迎文創業者、廠商及個人工作室申請，收件至115年11月23日止，入選名單預計12月底前公告，販售期間為116年全年。商品類別包括農特產、客家服飾、藍染與手作工藝、纏花等，投件時需於廠商資料表註明營業項目。", "sample": false, "url": "https://hk.hl.gov.tw/News_Content.aspx?n=10188&sms=15469&s=232132", "topic": "產業報導"}, {"id": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=8983c89ddd90646aea89a63a329c9138", "title": "市政新聞-侯友宜率千人挑擔 新北義民祭熱鬧登場青年親子吉祥物創意踩街 百人獻唱挺新北", "date": "2026-10-11", "category": "節慶活動", "unit": "新北市", "summary": "新北市客家事務局10月11日舉行義民祭挑擔奉飯創意踩街，市長侯友宜、客委會主委古秀妃與約三千至四千名鄉親自板橋第二運動場挑擔至市民廣場後舉行三獻禮。活動邀市府吉祥物、青年與學童合唱〈毋係一儕人〉；12日上午恭送聖駕回新埔枋寮義民廟。", "sample": false, "url": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=8983c89ddd90646aea89a63a329c9138"}, {"id": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=8983c89ddd90646a77c77b91c3454d2a", "title": "市政新聞-新北客家義民爺祭挑擔奉飯 侯友宜：推動客家文化「義起挺新北」", "date": "2026-10-11", "category": "節慶活動", "unit": "新北市", "summary": "新北市政府新聞局10月11日發布，115年客家義民爺文化祭同日舉行挑擔奉飯踩街與祭祀大典，市長侯友宜擔任主祭官，主題為「義起挺新北」。活動結合吉祥物、青年展演與百人合唱主題曲；12日上午將恭送義民爺返回新竹新埔枋寮義民廟。哈客館土城館已落成，鶯歌館預計11月啟用。", "sample": false, "url": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=8983c89ddd90646a77c77b91c3454d2a"}, {"id": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=96120605-8391-408c-ad51-8ccf73576c67", "title": "新北客家義民祭熱鬧登場 古主委：明年擴大設置都市伯公照護站", "date": "2026-10-11", "category": "節慶活動", "unit": "客家委員會全球資訊網", "summary": "客家委員會主委古秀妃10月11日出席新北客家義民祭祭祀大典並擔任主祭官，現場約三千至四千人挑擔奉飯。古主委表示，新北客家人口逾六十萬，客委會自明（116）年起將開放都市地區申請設置伯公照護站，擴大客家長者照顧。12日將恭送義民爺回新埔枋寮義民廟。", "sample": false, "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=96120605-8391-408c-ad51-8ccf73576c67"}, {"id": "https://www.cna.com.tw/news/aloc/202610110142.aspx", "title": "義民爺祭挑擔奉飯侯友宜：傳承客家文化", "date": "2026-10-11", "category": "節慶活動", "unit": "中央社", "summary": "新北市10月11日舉行客家義民爺文化祭挑擔奉飯踩街，市長侯友宜與客委會主委古秀妃等偕約三千至四千名鄉親自板橋第二運動場行約1.1公里至市民廣場，侯友宜並擔任祭祀大典主祭官。市府指出新北約有67.2萬客家人口，已設十一座哈客館，明年將再設泰山館。", "sample": false, "url": "https://www.cna.com.tw/news/aloc/202610110142.aspx"}, {"id": "https://news.immigration.gov.tw/NewsSection/Detail/63E2A722-37B2-437B-ADA6-8859CE5FCD7F?lang=TW&topic=onetouch", "title": "印尼山口洋客語仍是日常 15名青年踏查南洋客家新樣貌", "date": "2026-10-11", "category": "客語推廣", "unit": "內政部移民署", "summary": "臺北市客家文化基金會「2026全球客家串流計畫」帶領十五名青年赴印尼山口洋踏查，觀察當地客語日常使用及與達雅族交融的南洋客家樣貌。成果展自10月13日至29日於「客聚」及臺北市客家文化中心舉行，10月17日有成果發表會，民眾可依主辦單位公告參觀。", "sample": false, "url": "https://news.immigration.gov.tw/NewsSection/Detail/63E2A722-37B2-437B-ADA6-8859CE5FCD7F?lang=TW&topic=onetouch"}, {"id": "https://news.immigration.gov.tw/NewsSection/Detail/500E3AA3-16E4-40B2-97BC-01287C437E13?lang=TW", "title": "南投客家文化變身實境遊戲！跟著實習伯公「阿禾」走訪3大客庄", "date": "2026-10-11", "category": "客庄新聞", "unit": "內政部移民署", "summary": "南投縣客家發展所10月3日推出客家文化實境遊戲「伯公喊𠊎來代班」，串聯國姓鄉南天宮、草屯鎮太清宮及南投縣文化局三處起點，玩家掃描QR Code解謎探索客庄。遊戲開放至118年底；116年3月31日前完成可抽獎，首獎為日月潭溫泉酒店住宿券。", "sample": false, "url": "https://news.immigration.gov.tw/NewsSection/Detail/500E3AA3-16E4-40B2-97BC-01287C437E13?lang=TW"}, {"id": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=7a12cd55ea1a03028d58cb6b4def343c", "title": "市政新聞-三芝區農會茭白筍小旅行10月登場 結合藝術與客家風味", "date": "2026-10-10", "category": "客家文化", "unit": "新北市", "summary": "三芝區農會推出「2026芝心茭陪藝遊趣」一日遊程，10月24、31日各一場、每場20人。行程結合藝術走讀、直銷站選購、料理體驗、製作茭白筍泡菜與水梯田採筍，認識三芝客底飲食與農村生活。即日起報名，詳洽三芝區農會推廣部粉絲專頁。", "sample": false, "url": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=7a12cd55ea1a03028d58cb6b4def343c"}, {"id": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=377611f9c51f4574e901c45186c3fe97", "title": "市政新聞-新北市客家義民爺文化祭國慶開幕迎神安座大典羅文裕開唱、青創市集與旋轉木馬迎親子", "date": "2026-10-10", "category": "節慶活動", "unit": "新北市", "summary": "新北市「115年客家義民爺文化祭—義起挺新北」於10月10日在市民廣場開幕。客家局長劉冠吟與值年爐主前往新埔褒忠義民廟恭迎義民爺，副市長劉和然主持安座大典。活動含遶境、安座、酬神戲與藝文演出，金曲歌手羅文裕、吉那罐子登臺；另有青創市集、親子DIY與旋轉木馬。11日將舉行千人挑擔奉飯踩街。", "sample": false, "url": "https://www.ntpc.gov.tw/ch/home.jsp?id=e8ca970cde5c00e1&dataserno=377611f9c51f4574e901c45186c3fe97", "topic": "產業報導"}, {"id": "https://www.cna.com.tw/news/aloc/202610100099.aspx", "title": "新北客家義民祭安座登場傳承團結守護家園精神", "date": "2026-10-10", "category": "節慶活動", "unit": "中央社", "summary": "115年新北市客家義民爺文化祭10至11日在市政府廣場登場，10日先舉行義民爺遶境、安座與祭祀。副市長劉和然與客委會主任秘書吳克能出席；市府表示活動向先民致敬，傳承義民團結守護家園精神。11日將由市長侯友宜帶領挑擔奉飯與祭祀大典。", "sample": false, "url": "https://www.cna.com.tw/news/aloc/202610100099.aspx"}, {"id": "culture-indigo", "title": "【範例】社區教室解說客家藍染工序", "date": "2026-10-10", "category": "客家文化", "unit": "文化保存示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設一處社區教室安排藍染解說，只談染布前的準備、浸染與晾乾，不能報名，也不能當成課程公告。", "sample": true, "url": "article.html#culture-indigo"}, {"id": "policy-guidelines", "title": "【範例】補助要點改寫成短摘要時要附原文", "date": "2026-10-09", "category": "政策與補助", "unit": "政策整理示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設編輯要把一份公開補助要點收成短訊，摘要只能改寫條文裡已有的話，並留著原文出處。", "sample": true, "url": "article.html#policy-guidelines"}, {"id": "https://www.cna.com.tw/news/aloc/202610090201.aspx", "title": "竹縣藍營選情楊文科指充滿挑戰盼凝聚客家票", "date": "2026-10-09", "category": "客庄新聞", "unit": "中央社", "summary": "兼任國民黨竹縣黨部主委的縣長楊文科表示，這次選舉充滿挑戰，日前赴芎林力挺縣長參選人徐欣瑩、鄉長參選人陳星宏及議員參選人黃正彪，盼凝聚客庄力量、爭取客家選民支持，延續縣政與鄉政合作、推動客庄建設。", "sample": false, "url": "https://www.cna.com.tw/news/aloc/202610090201.aspx"}, {"id": "town-bus", "title": "【範例】山線客庄公車改點的公告會怎麼放", "date": "2026-10-08", "category": "客庄新聞", "unit": "北部客庄示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設客庄公車調整停靠，頁面上只會寫主辦單位已經公開的路線與日期，不推測對居民的影響。", "sample": true, "url": "article.html#town-bus"}, {"id": "https://www.tainan.gov.tw/News_Content.aspx?n=13371&s=8840741", "title": "舂粢粑鬥鬧熱 2026台南客家藝術節10/17水萍塭公園登場", "date": "2026-10-08", "category": "客家文化", "unit": "臺南市", "summary": "2026台南客家藝術節訂於10月17日在水萍塭公園登場，市府客委會8日舉辦宣傳記者會，副秘書長徐健麟代表市長出席並與貴賓舂粢粑暖身。活動以「多元族群嘉年華」為主題，晚間由榮興客家採茶劇團演出《天緣記》，並有市集、親子DIY與藝文表演，歡迎市民參加。", "sample": false, "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13371&s=8840741"}, {"id": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8840693", "title": "台南客家藝術節10/17水萍塭公園登場 黃偉哲：展現多元族群共融城市特色", "date": "2026-10-08", "category": "客家文化", "unit": "臺南市", "summary": "台南市長黃偉哲表示，2026台南客家藝術節10月17日將在水萍塭公園登場，串聯客家、原住民族及新住民文化，展現多元共融城市特色。市府8日辦宣傳會，副秘書長徐健麟代表出席。活動含客家大戲《天緣記》、市集、親子DIY及藝文表演，詳情見市府客委會粉絲專頁。", "sample": false, "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8840693"}, {"id": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&s=1003008", "title": "🍽️【2026客庄美饌・巧廚盛宴】訂桌報名即將開始！", "date": "2026-10-08", "category": "客庄新聞", "unit": "苗栗市公所", "summary": "苗栗市公所「2026客庄美饌・巧廚盛宴」訂桌報名將於10月12日上午10時起開放，額滿為止。今年至少180桌，每桌4,000元（限10人、含飲料2瓶），提供12道客家料理；每人最多訂4桌、無素食，繳費後恕不退訂。", "sample": false, "url": "https://www.mlcg.gov.tw/News_Content.aspx?n=2545&s=1003008"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&s=B211DA31D2EDC92C", "title": "兩代抵押土地守護華文教育、臺灣客家戲曲轟動南洋校園！", "date": "2026-10-08", "category": "全球客家", "unit": "臺北市", "summary": "台北市客家文化基金會「2026全球客家串流計畫」帶領15名青年至印尼山口洋新光明印華學校交流，見證海外華文辦學並演出客家戲曲與音樂。成果展10月13日至29日於客聚與臺北市客家文化中心展出，10月17日14時於客聚辦成果發表會。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=F0DDAF49B89E9413&s=B211DA31D2EDC92C"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=D0042A87C2F0270A&sms=78D644F2755ACCAA&s=C9FD342E5D1106BD", "title": "最新消息-新北市政府客家事務局公開徵求116年客家文化創意或設計商品寄賣，歡迎有興趣者遞件申請", "date": "2026-10-08", "category": "政策與補助", "unit": "臺北市", "summary": "新北市政府客家事務局文創商品店（三峽客家文化園區）公開徵求116年客家文化創意或設計商品寄賣，收件即日起至115年11月23日止。有意者請至新北客家局官網最新消息或園區官網訊息發佈查詢詳情並遞件申請。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=D0042A87C2F0270A&sms=78D644F2755ACCAA&s=C9FD342E5D1106BD", "topic": "產業報導"}, {"id": "https://www.gov.taipei/News_Content.aspx?n=D0042A87C2F0270A&s=F67A190A4DC6D9C2", "title": "最新消息-2026臺北客家義民嘉年華交通管制訊息", "date": "2026-10-08", "category": "節慶活動", "unit": "臺北市", "summary": "臺北市政府客家事務委員會公告，2026年10月24、25日「臺北客家義民嘉年華」迎神遶境及挑擔踩街期間將實施交通管制，詳細路段與時段請參閱市府官網附件。用路人請多留意改道與管制訊息。", "sample": false, "url": "https://www.gov.taipei/News_Content.aspx?n=D0042A87C2F0270A&s=F67A190A4DC6D9C2"}, {"id": "https://www.banqiao.ntpc.gov.tw/home.jsp?id=b6ef2e53ee690ce6&act=be4f48068b2b0031&dataserno=f2f3ae7ea21f31f6566f48c58c1c5f82", "title": "最新消息-新北市政府客家事務局文創商品店 116年商品寄賣徵件", "date": "2026-10-08", "category": "客家文化", "unit": "新北市", "summary": "新北市政府客家事務局文創商品店位於三峽客家文化園區，公開徵求116年寄賣文創商品，收件即日起至115年11月23日止。相關訊息請參閱新北客家事務局官網最新消息；板橋區公所亦轉知此徵件訊息。", "sample": false, "url": "https://www.banqiao.ntpc.gov.tw/home.jsp?id=b6ef2e53ee690ce6&act=be4f48068b2b0031&dataserno=f2f3ae7ea21f31f6566f48c58c1c5f82", "topic": "產業報導"}, {"id": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26840&sms=9749&s=8840741", "title": "臺南市政府客家事務委員會-舂粢粑鬥鬧熱2026台南客家藝術節10/17水萍塭公園登場", "date": "2026-10-08", "category": "客家文化", "unit": "臺南市", "summary": "2026台南客家藝術節將於10月17日在水萍塭公園登場，市府客委會8日辦宣傳記者會，副秘書長徐健麟代表市長出席並與貴賓舂粢粑。活動以「多元族群嘉年華」為主題，晚間榮興客家採茶劇團演出《天緣記》，並有市集、親子DIY與藝文表演，詳見客委會粉絲專頁。", "sample": false, "url": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26840&sms=9749&s=8840741"}, {"id": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26840&sms=9749&s=8840699", "title": "臺南市政府客家事務委員會-【共下．共好】楠西駐地工作站成果展✕ 手作與永續體驗課程開放報名!", "date": "2026-10-08", "category": "客家文化", "unit": "臺南市", "summary": "臺南市客委會「共下．共好」楠西駐地工作站成果展訂於10月18日在客家文化會館三樓大禮堂免費舉辦，開放印香、皮革編織手環、古厝文化轉印、藍碳永續桌遊等體驗課程，採網路報名額滿為止，當日亦保留部分現場名額。", "sample": false, "url": "https://web.tainan.gov.tw/hakka/News_Content.aspx?n=26840&sms=9749&s=8840699"}, {"id": "lang-parents", "title": "【範例】國小客語課家長說明會先寫清楚對象", "date": "2026-10-07", "category": "客語推廣", "unit": "客語教學示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設學校辦客語課說明會，摘要會先寫給誰參加、使用哪一種腔調的教材，不排名、不比較家庭。", "sample": true, "url": "article.html#lang-parents"}, {"id": "fest-tung", "title": "【範例】桐花活動預告要一併寫交通與無障礙", "date": "2026-10-06", "category": "節慶活動", "unit": "節慶企劃示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設桐花季有一場公開活動，預告除了時間地點，也會留交通方式與無障礙資訊，缺資料就明寫尚未公告。", "sample": true, "url": "article.html#fest-tung"}, {"id": "tour-walk", "title": "【範例】客庄半日走讀標出休息與廁所", "date": "2026-10-05", "category": "產業與觀光", "unit": "觀光路線示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設一條客庄走讀路線被寫成短訊，會標休息點與廁所，不承諾風景，也不替商家背書。", "sample": true, "url": "article.html#tour-walk"}, {"id": "https://www.juisui.gov.tw/News_Content.aspx?n=3419&sms=10680&s=231646", "title": "2026/10/03 瑞穗「食在好客」體驗活動登場 串聯美食農產品味文化客庄 感受客家人情與生活智慧", "date": "2026-10-05", "category": "產業與觀光", "unit": "juisui.gov.tw", "summary": "花蓮縣瑞穗鄉公所10月3日舉辦「食在好客」客家文化體驗活動，設「客庄好食市集」，邀在地農友、社區組織、特色商家與青年創業團隊展售瑞穗米、蜜香紅茶、咖啡、客家米食與伴手禮，並有客語闖關、糍粑與擂茶DIY及客家藝文展演。縣長徐榛蔚表示將客家文化與在地產業、觀光結合。", "sample": false, "url": "https://www.juisui.gov.tw/News_Content.aspx?n=3419&sms=10680&s=231646", "topic": "產業報導"}, {"id": "world-hall", "title": "【範例】海外客家會館的公開活動只摘公告", "date": "2026-10-04", "category": "全球客家", "unit": "海外社群示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設海外一處客家會館公布聚會，摘要只轉述該則公告的時間與性質，不描述現場，也不引述任何人。", "sample": true, "url": "article.html#world-hall"}, {"id": "culture-food", "title": "【範例】客家常民飲食寫進社區導覽的方式", "date": "2026-10-03", "category": "客家文化", "unit": "飲食文化示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設社區導覽要介紹客家常民飲食，用詞維持日常，不把食物寫成奇觀，也不捏造老店名號。", "sample": true, "url": "article.html#culture-food"}, {"id": "policy-window", "title": "【範例】縣市客家業務摘要要留下承辦窗口", "date": "2026-10-02", "category": "政策與補助", "unit": "地方計畫示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設縣市公布客家業務說明，摘要會留下承辦單位的公開窗口；窗口若還沒公告，就寫尚未公布，不自編電話。", "sample": true, "url": "article.html#policy-window"}, {"id": "town-care", "title": "【範例】沿海客庄照顧據點只寫開放時間", "date": "2026-10-01", "category": "客庄新聞", "unit": "南部客庄示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設沿海客庄一處社區照顧據點調整開放時間，頁面只列已公布的時段，不描述個案，也不評價服務好壞。", "sample": true, "url": "article.html#town-care"}, {"id": "lang-cert", "title": "【範例】客語能力認證資訊必須連回官方頁", "date": "2026-09-30", "category": "客語推廣", "unit": "客語教學示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設要提醒客語能力認證的報名訊息，正式稿必須連回主管機關頁面。這一則沒有連結，因為它不是公告。", "sample": true, "url": "article.html#lang-cert"}, {"id": "fest-yimin", "title": "【範例】義民祭的流程說明先寫清信仰脈絡", "date": "2026-09-29", "category": "節慶活動", "unit": "祭典紀錄示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設要寫義民祭的公開流程，會先用尊重的語氣交代信仰脈絡，不獵奇，也不把單一廟會寫成全臺統一作法。", "sample": true, "url": "article.html#fest-yimin"}, {"id": "tour-harvest", "title": "【範例】在地農產訊息不寫未查證的產量", "date": "2026-09-28", "category": "產業與觀光", "unit": "客庄產業示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設客庄農產進入產季，摘要只會寫已公布的品項與集貨訊息，不編造產量、價格或得獎紀錄。", "sample": true, "url": "article.html#tour-harvest"}, {"id": "world-statement", "title": "【範例】海外社團聲明要先核對原文語言", "date": "2026-09-27", "category": "全球客家", "unit": "海外社群示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設海外客家社團發表公開聲明，編輯會先核對原文語言與發布者，再寫中文摘要，不把聲明說成臺灣政策。", "sample": true, "url": "article.html#world-statement"}, {"id": "culture-song", "title": "【範例】山歌與八音欣賞課避免刻板印象", "date": "2026-09-26", "category": "客家文化", "unit": "文化保存示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設社區辦山歌與八音欣賞課，介紹會說明曲類與場合，不用外貌或口音當笑點，也不杜撰演出者姓名。", "sample": true, "url": "article.html#culture-song"}, {"id": "policy-school", "title": "【範例】學校申請客語資源時分步驟說明", "date": "2026-09-25", "category": "政策與補助", "unit": "政策整理示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設要說明學校如何申請客語教學資源，正式稿會按公開程序分步驟寫，並註明以主管機關最新頁面為準。", "sample": true, "url": "article.html#policy-school"}, {"id": "town-library", "title": "【範例】客庄圖書館夜間開館的消息格式", "date": "2026-09-24", "category": "客庄新聞", "unit": "中部客庄示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設客庄圖書館試辦夜間開館，訊息只包含已公布的館別、星期與閉館日，不寫尚未決定的活動。", "sample": true, "url": "article.html#town-library"}, {"id": "lang-radio", "title": "【範例】客語廣播說新聞時標示播出時間", "date": "2026-09-23", "category": "客語推廣", "unit": "客語媒體示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設有客語新聞廣播，介紹會標示頻道與時段，並說明這是節目資訊，不是本站自己製作的客語新聞。", "sample": true, "url": "article.html#lang-radio"}, {"id": "fest-sky", "title": "【範例】天穿日預告不拼湊沒有來源的由來", "date": "2026-09-22", "category": "節慶活動", "unit": "祭典紀錄示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設社區要預告天穿日活動，由來只採用已標出處的說法；出處不足就只寫活動本身，不補傳說。", "sample": true, "url": "article.html#fest-sky"}, {"id": "tour-stay", "title": "【範例】客庄旅宿介紹不代讀者保證品質", "date": "2026-09-21", "category": "產業與觀光", "unit": "觀光路線示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設要列出客庄旅宿的公開資訊，只轉述業者或主管機關已公布的內容，不保證品質，也不排序推薦。", "sample": true, "url": "article.html#tour-stay"}, {"id": "https://www.cna.com.tw/news/aloc/202609210173.aspx", "title": "屏東客庄產業培力打造地方品牌新亮點", "date": "2026-09-21", "category": "產業與觀光", "unit": "中央社", "summary": "屏東縣客庄產業培力課程9月21日在屏東客家文化中心結訓，本期31名學員以8週學習品牌定位與數位行銷。縣長周春米表示縣府將當客庄業者後盾。客務處指出，前2屆已有40家業者參與，產生12項創新產品、開發6處通路並促成13項異業合作，例如以客庄可可開發可可酒、麵包店開設新門市。", "sample": false, "url": "https://www.cna.com.tw/news/aloc/202609210173.aspx", "topic": "產業報導"}, {"id": "world-youth", "title": "【範例】跨國青年客語交換不宣稱有官方名額", "date": "2026-09-20", "category": "全球客家", "unit": "青年交流示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設有人詢問跨國青年客語交換，沒有公開名額之前，頁面不會寫成已經開辦，也不會替任何機關招生。", "sample": true, "url": "article.html#world-youth"}, {"id": "culture-house", "title": "【範例】老夥房空間紀錄改成民眾看得懂的話", "date": "2026-09-19", "category": "客家文化", "unit": "文化保存示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設要把夥房空間紀錄改寫給一般讀者，會解釋廳堂與生活功能，不公布私人門牌，也不當作文資指定公告。", "sample": true, "url": "article.html#culture-house"}, {"id": "policy-access", "title": "【範例】補助說明會同時寫無障礙參加方式", "date": "2026-09-18", "category": "政策與補助", "unit": "地方計畫示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設機關辦補助說明會，正式預告會一併寫聽打、無障礙席位或線上參加；沒有這些資訊就標明尚未說明。", "sample": true, "url": "article.html#policy-access"}, {"id": "https://www.kcg.gov.tw/CityNews_Detail1.aspx?n=3A379BB94CA5F12D&ss=AD0F8E578A8BE836", "title": "【代發青年局新聞稿】留美夫妻返鄉創業美式雞翅飄香客庄美濃青創店家「沒事去啃」中秋到府烤肉免備料", "date": "2026-09-18", "category": "產業與觀光", "unit": "高雄市", "summary": "高雄市青年局長林楷軒走訪美濃青創店家「沒事去啃」。負責人陳逸豪與妻子黃婕妮留美後返回美濃創業，復刻水牛城雞翅，並用美濃147米自製鹽麴醃漬豬肉，另推出午餐盒、冷凍宅配與到府烤肉服務。青年局表示持續提供青創租金與生財器具補助，協助返鄉青年降低創業初期負擔。", "sample": false, "url": "https://www.kcg.gov.tw/CityNews_Detail1.aspx?n=3A379BB94CA5F12D&ss=AD0F8E578A8BE836", "topic": "產業報導"}, {"id": "town-east", "title": "【範例】偏鄉客庄行動服務到村里的預告", "date": "2026-09-17", "category": "客庄新聞", "unit": "東部客庄示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設偏鄉客庄有行動服務進到村里，預告只寫已公布的地點與項目，不收集民眾個資，也不保證當日一定到場。", "sample": true, "url": "article.html#town-east"}, {"id": "lang-home", "title": "【範例】家庭客語練習單不評比也不排名", "date": "2026-09-16", "category": "客語推廣", "unit": "客語媒體示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設推廣家庭使用客語的練習單，說明會強調自願、不評比、不公開家庭分數，也不嘲諷腔調差異。", "sample": true, "url": "article.html#lang-home"}, {"id": "fest-meal", "title": "【範例】收冬共餐只寫主辦單位公開的資訊", "date": "2026-09-15", "category": "節慶活動", "unit": "節慶企劃示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設客庄在收成後辦社區共餐，稿件只採用主辦單位公開的時間與參加方式，不描寫個別家庭。", "sample": true, "url": "article.html#fest-meal"}, {"id": "tour-market", "title": "【範例】假日市集攤位以主辦單位公告為準", "date": "2026-09-14", "category": "產業與觀光", "unit": "客庄產業示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設客庄假日市集要見報，攤位與營業時間以主辦單位公告為準，臨時改期就更正，不沿用過期傳單。", "sample": true, "url": "article.html#tour-market"}, {"id": "world-genealogy", "title": "【範例】族譜數位化要先提醒個資界線", "date": "2026-09-13", "category": "全球客家", "unit": "青年交流示範組", "summary": "【範例稿】此為虛構情境，非正式新聞，沒有受訪者。假設有族譜數位化的公開說明，摘要會先提醒姓名與親屬關係屬於個人資料，本站不收族譜、也不代為公開。", "sample": true, "url": "article.html#world-genealogy"}, {"id": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&sms=9748&s=8836478", "title": "從客底文化走進地方創生 臺南客委會攜手高科大深度踏查楠西聚落", "date": "2026-09-13", "category": "產業與觀光", "unit": "臺南市", "summary": "臺南市客委會「臺南原鄉客家聚落青年駐地工作站計畫」與高雄科技大學於9月12日至13日辦理「楠西再生．關懷小旅行」，邀高師大客家文化研究所師生踏查鹿陶洋江家古厝等客底聚落與信仰空間，並走訪在地店家。參與學者指出，客底聚落正嘗試以六級化產業轉型，田野紀錄將作為楠西地方創生規劃素材。", "sample": false, "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&sms=9748&s=8836478", "topic": "產業報導"}, {"id": "https://www.cna.com.tw/news/aloc/202608280169.aspx", "title": "南投學研討會探討客家歷史文化與產業發展", "date": "2026-08-28", "category": "產業與觀光", "unit": "中央社", "summary": "南投縣文化局與客家發展所8月28日舉辦「南投客蹤新聲」南投學研討會，邀專家學者、客家協會與產業代表，從歷史、族群、建築延伸到產業與文化觀光，探討南投客家聚落、宗祠、語言、水圳與藍染等議題。8篇投稿論文審查後選出7篇發表，盼研究成果與地方實際發展相互連結。", "sample": false, "url": "https://www.cna.com.tw/news/aloc/202608280169.aspx", "topic": "產業報導"}, {"id": "https://www.hl.gov.tw/News_Content.aspx?n=32725&s=229192", "title": "「笠下花蓮．客庄百工」串聯文化、產業與觀光 2026客家產業暨技藝博覽會8月29日盛大登場", "date": "2026-08-26", "category": "產業與觀光", "unit": "花蓮縣", "summary": "花蓮縣政府8月29日至9月13日舉辦「2026客家產業暨技藝博覽會」，以「笠下花蓮．客庄百工」為主題，邀請臺三線、六堆及臺九線客庄的特色產業與技藝團隊參展，在花蓮縣客家文化園區及日出大道設雙展區，規劃職人示範、特色市集、手作體驗與展演，並推出限量三倍券可於客家市集消費使用。", "sample": false, "url": "https://www.hl.gov.tw/News_Content.aspx?n=32725&s=229192", "topic": "產業報導"}, {"id": "https://www.cna.com.tw/news/aloc/202608180187.aspx", "title": "新竹北埔睡虎宴串聯老街業者客家美食行銷在地", "date": "2026-08-18", "category": "產業與觀光", "unit": "中央社", "summary": "新竹縣政府與北埔老街商圈8月18日發表「北埔睡虎宴」，以北埔「睡虎型」地理意象為品牌，串聯老街10多家餐飲、小吃及伴手禮業者推出客家特色宴席，10月17日在北埔慈天宮前廣場登場。菜色包括阿婆酸菜鴨、梅干扣肉、客家鹹湯圓等，並搭配擂茶、柿糬等在地伴手禮行銷客庄產業。", "sample": false, "url": "https://www.cna.com.tw/news/aloc/202608180187.aspx", "topic": "產業報導"}];
window.UPDATED="2026-10-30 05:07";
